window.SLIDES=[{"id": "s_trachea", "name": "Trachea", "day": "Day 1–2 · Epithelial/connective + hyaline cartilage", "course": "images/course/trachea.jpg", "identify": ["Ciliated pseudostratified columnar epithelium on the lumen surface (nuclei at different heights, cilia)", "Thick purple band of hyaline cartilage with chondrocytes in lacunae", "Perichondrium on both sides of the cartilage", "Adipose tissue outside", "Goblet cells in the epithelium; seromucous glands in the submucosa"], "label": ["Ciliated pseudostratified columnar epithelium (with goblet cells)", "Basement membrane", "Lamina propria / submucosa: loose connective tissue (fibroblasts + collagen type I matrix) with seromucous glands", "Blood vessels (endothelium; simple squamous epithelium)", "Perichondrium (dense irregular connective tissue)", "Chondroblast (in perichondrium)", "Hyaline cartilage (collagen type II matrix)", "Chondrocytes in lacunae (isogenous groups)", "Adventitia / adipose tissue"], "layers": ["Mucosa: ciliated pseudostratified columnar epithelium + lamina propria (loose CT)", "Submucosa: loose CT with seromucous glands and blood vessels", "Hyaline cartilage (C-shaped ring) with perichondrium on both sides", "Adventitia with adipose tissue"], "model": "This is the trachea. From the lumen outwards: the mucosa is lined by a ciliated pseudostratified columnar epithelium (respiratory epithelium) – one layer of cells, all on the basement membrane, but with nuclei at different heights, cilia on the surface and goblet cells. Beneath it is loose connective tissue (fibroblasts and a collagen type I matrix) of the lamina propria and submucosa, with seromucous glands and blood vessels lined by endothelium (simple squamous epithelium). Next is the hyaline cartilage ring, surrounded on both sides by perichondrium of dense irregular connective tissue, where chondroblasts are found. The cartilage has a homogeneous matrix of collagen type II with chondrocytes inside lacunae, often in isogenous groups. Outside is the adventitia with adipose tissue.", "key": ["Trachea", "Ciliated pseudostratified columnar epithelium + goblet cells", "Loose CT (lamina propria/submucosa), glands, blood vessels", "Perichondrium = dense irregular CT, chondroblasts", "Hyaline cartilage, collagen type II", "Chondrocytes in lacunae", "Adventitia / adipose tissue"], "src": "https://commons.wikimedia.org/wiki/File:Trachea_(mammal)_histology_cross-section.png", "title": "File:Trachea (mammal) histology cross-section.png", "author": "Magscope", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "images/s_trachea.jpg", "img": "images/course/sem_trachea.jpg", "more": [{"img": "images/course/sem_trachea.jpg", "cap": "Course seminar image (unlabelled)"}], "notes": []}, {"id": "s_thick_skin", "name": "Thick skin", "day": "Day 1 · Epithelial/connective", "course": "images/course/thick_skin.jpg", "identify": ["Very thick stratum corneum (keratin) on top – palm/sole", "Keratinized stratified squamous epithelium with deep epidermal ridges", "NO hair follicles or sebaceous glands (that's thin skin)", "Sweat glands deep in dermis; hypodermis with adipocytes"], "label": ["Keratin (stratum corneum)", "Epidermis (keratinized stratified squamous epithelium) – strata basale, spinosum, granulosum, lucidum, corneum", "Dermis: papillary (loose CT) + reticular (irregular dense connective tissue: fibroblasts + collagen type I)", "Blood vessels (endothelium)", "Sweat gland (simple coiled tubular gland; duct = bistratified cuboidal epithelium)", "Hypodermis (connective tissue + adipose tissue; adipocytes)"], "layers": ["Epidermis (keratinized stratified squamous) with thick keratin", "Dermis (papillary + reticular; irregular dense CT)", "Hypodermis (CT + adipose tissue)"], "model": "This is thick skin. The surface is covered by a very thick layer of keratin (stratum corneum) on top of the epidermis, a keratinized stratified squamous epithelium; from deep to superficial it has the strata basale, spinosum, granulosum, lucidum and corneum. Beneath it is the dermis: a thin papillary layer of loose connective tissue in the dermal papillae and a thick reticular layer of irregular dense connective tissue, made of fibroblasts and a collagen type I matrix, with blood vessels (endothelium; simple squamous epithelium). In the deep dermis there are sweat glands – simple coiled tubular glands whose ducts are lined by a bistratified cuboidal epithelium. There are no hair follicles. The deepest layer is the hypodermis, connective tissue with abundant adipose tissue (adipocytes).", "key": ["Thick skin", "Very thick keratin / stratum corneum", "Epidermis = keratinized stratified squamous epithelium (5 strata)", "Dermis = irregular dense CT (fibroblasts + collagen I)", "Sweat glands: simple coiled tubular, bistratified cuboidal duct", "No hair follicles", "Hypodermis with adipocytes"], "src": "https://commons.wikimedia.org/wiki/File:Histology_of_thick_skin.jpg", "title": "File:Histology of thick skin.jpg", "author": "Bhavya akula", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "images/s_thick_skin.jpg", "img": "images/course/thick_skin_unlabeled.jpg", "more": [], "notes": ["The guide labels the hypodermis as 'irregular dense connective tissue + adipose tissue'; most textbooks (Wheater) describe it as loose connective tissue + adipose. Say 'connective tissue with adipose tissue (adipocytes)' to be safe."]}, {"id": "s_thyroid", "name": "Thyroid", "day": "Day 1 · Glandular epithelium", "course": "images/course/thyroid.jpg", "identify": ["Many round follicles filled with pink colloid", "Follicles lined by a single layer of follicular cells (simple cuboidal; flatter when inactive)", "Clear parafollicular cells between follicles", "No ducts – endocrine gland"], "label": ["Capsule (connective tissue)", "Follicles", "Colloid (thyroglobulin)", "Follicular cells – simple cuboidal epithelium (guide labels it 'simple squamous')", "Parafollicular (C) cells", "Blood capillaries between follicles"], "layers": ["Connective tissue capsule", "Parenchyma of follicles (epithelium + colloid)", "Parafollicular cells + connective tissue between follicles"], "model": "This is the thyroid, a follicular endocrine gland. It is covered by a connective tissue capsule, and its parenchyma is made of many round follicles of different sizes. Each follicle is lined by a single layer of follicular cells – a simple cuboidal epithelium, which becomes flatter (squamous) when the gland is inactive – and its lumen is filled with pink, homogeneous colloid (thyroglobulin). Between the follicles there are larger, paler parafollicular (C) cells, plus thin connective tissue with many blood capillaries. It has no ducts because it is an endocrine gland: it secretes its hormones into the blood.", "key": ["Thyroid – follicular endocrine gland", "Follicles", "Colloid", "Follicular cells: simple cuboidal (flat when inactive)", "Parafollicular cells", "Capsule / capillaries / no ducts"], "src": "https://commons.wikimedia.org/wiki/File:Thyroid_gland_microscope.jpg", "title": "File:Thyroid gland microscope.jpg", "author": "Lazar.zenit", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "images/s_thyroid.jpg", "img": "images/course/thyroid_unlabeled.jpg", "more": [], "notes": ["Course guide labels the follicle wall 'simple squamous tissue'. Standard histology (Wheater): simple cuboidal, flattening to squamous when inactive. In the exam say 'simple cuboidal, which can look squamous/flattened' – that covers both."]}, {"id": "s_tendon", "name": "Tendon", "day": "Day 1 · Connective tissue", "course": "images/course/tendon.jpg", "identify": ["Parallel, tightly packed pink collagen bundles", "Rows of elongated flat fibroblast nuclei between bundles", "Few cells, almost no ground substance", "Compare with dense IRREGULAR CT (fibres in all directions)", "Nuclei are flat and squeezed between collagen bundles – no cell membranes or striations"], "label": ["Dense regular connective tissue", "Organized collagen type I fibers", "Fibroblasts", "Specialized fibroblasts (tenocytes)", "Longitudinal vs cross section"], "layers": ["Dense regular connective tissue (with surrounding dense irregular CT)"], "model": "This is a tendon, made of dense regular connective tissue. In longitudinal section the collagen type I fibers are organized parallel to each other in thick bundles, and between them there are rows of elongated, flattened nuclei of fibroblasts (specialized fibroblasts). In cross section the bundles look like pink areas with scattered fibroblast nuclei. It differs from dense irregular connective tissue, where collagen type I fibers run in all directions.", "key": ["Tendon", "Dense regular connective tissue", "Organized parallel collagen type I fibers", "Fibroblasts / specialized fibroblasts in rows", "Longitudinal vs cross section", "Contrast with dense irregular CT"], "src": "https://commons.wikimedia.org/wiki/File:Dense_regular1.jpg", "title": "File:Dense regular1.jpg", "author": "Echinaceapallida", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "images/s_tendon.jpg", "img": "images/course/tendon_unlabeled.jpg", "more": [], "notes": ["Look-alike: smooth muscle also has elongated nuclei, but its cells have pink cytoplasm with cigar-shaped nuclei in the centre of each cell, and nuclei are more numerous. In tendon most of the area is acellular collagen."]}, {"id": "s_compact_bone", "name": "Compact bone (ground section)", "day": "Day 2 · Bone", "course": "images/course/compact_bone.jpg", "identify": ["Unstained ground section (grey/brown, no cells' colour)", "Osteons: concentric lamellae around a central Haversian canal", "Dark lacunae with thin canaliculi", "Volkmann canals crossing between osteons"], "label": ["Osteons (Haversian systems)", "Haversian (central) canal", "Concentric lamellae", "Interstitial lamellae (between osteons)", "Osteocytes in lacunae", "Canaliculi (guide: 'chacophore canaliculi' – from Spanish 'canalículos calcóforos')", "Volkmann (perforating) canal"], "layers": ["Osteons with concentric lamellae", "Interstitial lamellae between osteons"], "model": "This is compact bone in a ground (unstained, non-decalcified) section. It is formed by osteons or Haversian systems: each has a central Haversian canal, which carries blood vessels and nerves, surrounded by concentric lamellae of mineralized bone matrix. Between the lamellae there are osteocytes inside lacunae, which connect to each other and to the canal through thin canaliculi. Between the osteons there are interstitial lamellae, and Volkmann (perforating) canals run transversely, connecting neighbouring Haversian canals.", "key": ["Compact bone, ground section", "Osteons", "Haversian canal", "Concentric lamellae", "Osteocytes in lacunae", "Canaliculi", "Volkmann canal", "Interstitial lamellae"], "src": "https://commons.wikimedia.org/wiki/File:Compact_bone_-_ground_cross_section.jpg", "title": "File:Compact bone - ground cross section.jpg", "author": "unknown", "license": "CC BY-SA 3.0", "licurl": "http://creativecommons.org/licenses/by-sa/3.0/", "commons": "images/s_compact_bone.jpg", "img": "images/s_compact_bone.jpg", "more": [], "notes": ["'Chacophore canaliculi' in the guide is a mistranslation of Spanish 'canalículos calcóforos' = canaliculi. Use the word 'canaliculi'."]}, {"id": "s_spongy_bone", "name": "Spongy / cancellous bone", "day": "Day 2 · Bone", "course": "images/course/spongy_bone.jpg", "identify": ["Network of thin pink bony trabeculae (no osteons/Haversian systems)", "Spaces between trabeculae filled with red bone marrow (hematopoietic cells, adipocytes)", "Osteoblasts lining trabecular surfaces; large multinucleated osteoclasts", "Periosteum outside; skeletal muscle may be nearby (decalcified H&E section)"], "label": ["Periosteum (dense irregular CT + collagen type I + osteoblasts)", "Trabeculae (mineralized bone matrix)", "Medullary cavity / bone marrow with hematopoietic cells", "Osteoblast", "Osteocyte", "Osteoclast", "Skeletal striated muscle (nearby)"], "layers": ["Periosteum", "Trabeculae of spongy bone", "Bone marrow in medullary cavity"], "model": "This is spongy (cancellous or trabecular) bone in a decalcified H&E section. It is covered by the periosteum, dense irregular connective tissue with collagen type I and osteoblasts. Inside there is a network of trabeculae of mineralized bone matrix, without osteons or Haversian systems. Osteocytes sit in lacunae inside the trabeculae; on their surfaces there are osteoblasts in a row and large multinucleated osteoclasts. The spaces between the trabeculae form the medullary cavity, filled with bone marrow containing hematopoietic cells. Skeletal striated muscle can be seen next to the bone.", "key": ["Spongy/cancellous bone", "Trabeculae (mineralized matrix), no osteons", "Periosteum", "Bone marrow with hematopoietic cells", "Osteoblasts", "Osteocytes", "Osteoclasts"], "src": null, "title": null, "author": "Robert M. Hunt", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": null, "img": "images/course/spongy_bone_unlabeled.jpg", "more": [], "notes": []}, {"id": "s_blood", "name": "Blood smear", "day": "Day 2 · Blood", "course": "images/course/blood_smear.jpg", "identify": ["Many pink, anucleate red blood cells with pale centre", "Scattered white blood cells with purple nuclei", "Tiny purple platelets"], "label": ["Red blood cells (erythrocytes)", "Platelet", "Neutrophil (multilobed nucleus)", "Lymphocyte (large round nucleus, thin cytoplasm rim)", "Monocyte (largest, kidney-shaped nucleus)", "Eosinophil (bilobed nucleus, orange-red granules)", "Basophil (dark blue granules covering nucleus)"], "layers": ["No layers – smear of cells"], "model": "This is a blood smear. Most cells are red blood cells: biconcave, anucleate, pink, with a pale centre. Platelets are small purple fragments without a nucleus. Among the white blood cells I can see: the neutrophil, with a multilobed nucleus and pale granules; the lymphocyte, small, with a large round dark nucleus and a thin rim of cytoplasm; the monocyte, the largest, with a kidney-shaped nucleus; the eosinophil, with a bilobed nucleus and orange-red granules; and the basophil, with dark blue-purple granules that hide the nucleus.", "key": ["Blood smear", "Red blood cells – anucleate, biconcave", "Platelets", "Neutrophil – multilobed", "Lymphocyte – round nucleus", "Monocyte – kidney nucleus, largest", "Eosinophil – bilobed, red granules", "Basophil – dark granules"], "src": "https://commons.wikimedia.org/wiki/File:Normal_Adult_Blood_Smear.JPG", "title": "File:Normal Adult Blood Smear.JPG", "author": "Keith Chambers", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "images/s_blood.jpg", "img": "images/s_blood.jpg", "more": [], "notes": []}, {"id": "s_tongue", "name": "Tongue", "day": "Day 2 · Striated skeletal muscle", "course": "images/course/tongue.jpg", "identify": ["Keratinized stratified squamous epithelium with papillae on top", "Underlying irregular dense CT", "Skeletal muscle fascicles running in three planes (longitudinal + cross sections in the same slide)"], "label": ["Keratinized stratified squamous epithelium", "Irregular dense connective tissue (fibroblasts, collagen type I, blood vessels)", "Fascicles", "Skeletal striated muscle", "Muscle fibers = muscle cells (peripheral nuclei, multinucleated)", "Striations", "Loose connective tissue (guide: 'smooth connective tissue') between fibres"], "layers": ["Epithelium (keratinized stratified squamous)", "Irregular dense connective tissue", "Skeletal striated muscle in fascicles"], "model": "This is the tongue. The surface is covered by a keratinized stratified squamous epithelium that forms papillae (in the guide's slide it is keratinized; in humans the dorsum is partially keratinized). Beneath it is irregular dense connective tissue with fibroblasts, a collagen type I matrix and blood vessels (endothelium). Most of the organ is skeletal striated muscle organized in fascicles that run in three directions, so I see fibers in longitudinal and in cross section. The muscle fibers are muscle cells: long, cylindrical, multinucleated, with peripheral nuclei and transverse striations; in cross section they are polygonal with nuclei at the edge. Between the fibers there is loose connective tissue (endomysium/perimysium).", "key": ["Tongue", "Keratinized stratified squamous epithelium", "Irregular dense CT + blood vessels", "Skeletal striated muscle in fascicles", "Fibers in longitudinal AND cross section", "Multinucleated, peripheral nuclei", "Striations"], "src": "https://commons.wikimedia.org/wiki/File:%D0%9F%D0%BE%D0%BF%D0%B5%D1%80%D0%B5%D1%87%D0%BD%D0%B0%D1%8F_%D0%BC%D1%8B%D1%88%D0%B5%D1%87%D0%BD%D0%B0%D1%8F_%D1%82%D0%BA%D0%B0%D0%BD%D1%8C_%D1%8F%D0%B7%D1%8B%D0%BA%D0%B0.jpg", "title": "File:Поперечная мышечная ткань языка.jpg", "author": "Molecularu", "license": "CC0", "licurl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en", "commons": null, "img": "images/course/tongue_unlabeled.jpg", "more": [{"img": "images/course/sem_skeletal_muscle.jpg", "cap": "Course seminar image: skeletal striated muscle, longitudinal (striations, peripheral nuclei)"}], "notes": []}, {"id": "s_heart", "name": "Heart (cardiac muscle)", "day": "Day 2 · Striated cardiac muscle", "course": "images/course/heart.jpg", "identify": ["Striated branched cells", "Single CENTRAL nucleus per cell", "Intercalated disks (dark transverse lines)", "Loose CT and capillaries between fibres"], "label": ["Cardiac striated muscle (cardiomyocytes)", "Striations", "Nucleus (central, 1–2 per cell, often with a pale perinuclear halo)", "Intercalated disks", "Branching fibers", "Loose connective tissue (guide: 'smooth connective tissue')", "Blood vessel / capillaries (endothelium; simple squamous epithelium)"], "layers": ["Myocardium (cardiac muscle) with connective tissue and vessels"], "model": "This is the heart, formed by cardiac striated muscle made of cardiomyocytes. In longitudinal section the cells are branched and show striations, with one central nucleus (sometimes two) and intercalated disks, the dark transverse lines that join neighbouring cells. In cross section the cells are rounded with a central nucleus. Between the cells there is loose connective tissue with blood vessels lined by endothelium (simple squamous epithelium).", "key": ["Heart / cardiac striated muscle", "Cardiomyocytes, branched", "Striations", "Central nucleus", "Intercalated disks", "Connective tissue + blood vessels"], "src": "https://commons.wikimedia.org/wiki/File:Cardiac_muscle_histology_400x.jpg", "title": "File:Cardiac muscle histology 400x.jpg", "author": "Alexander G. Cheroske", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "images/s_heart.jpg", "img": "images/s_heart.jpg", "more": [], "notes": ["Look-alike: skeletal muscle (tongue) – peripheral nuclei, no branching, no intercalated disks."]}, {"id": "s_artery_vein", "name": "Muscular artery and vein", "day": "Day 3 · Smooth muscle", "course": "images/course/artery_vein.jpg", "identify": ["Two vessels side by side in adipose tissue", "Artery: round, thick tunica media of smooth muscle, wavy internal elastic lamina", "Vein: larger, irregular/collapsed lumen with blood, thin media, thick adventitia"], "label": ["Muscular artery", "Vein", "Lumen", "Tunica intima (endothelium, simple squamous epithelium)", "Internal elastic lamina", "Tunica media (smooth muscle)", "External elastic lamina", "Tunica adventitia (dense irregular CT)", "Adipose tissue (adipocytes)"], "layers": ["Tunica intima", "(Internal elastic lamina – artery)", "Tunica media", "(External elastic lamina – artery)", "Tunica adventitia"], "model": "This sample shows a muscular artery and a vein, surrounded by adipose tissue. Both walls have three layers (tunicae). The tunica intima is the endothelium, a simple squamous epithelium lining the lumen. In the artery, the intima is followed by a wavy internal elastic lamina, then a thick tunica media of circularly arranged smooth muscle, an external elastic lamina, and the tunica adventitia of dense irregular connective tissue. The artery has a round lumen and a thick wall compared with its lumen. The vein has a larger, irregular or collapsed lumen, often containing blood cells, a thin tunica media of smooth muscle without clear elastic laminae, and a relatively thick tunica adventitia of dense irregular connective tissue.", "key": ["Muscular artery AND vein", "Tunica intima = endothelium", "Internal + external elastic laminae (artery)", "Tunica media = smooth muscle (thick in artery)", "Tunica adventitia = dense irregular CT", "Vein: wide irregular lumen, thin media", "Adipose tissue"], "src": "https://commons.wikimedia.org/wiki/File:2102_Comparison_of_Artery_and_Vein.jpg", "title": "File:2102 Comparison of Artery and Vein.jpg", "author": "OpenStax College", "license": "CC BY 3.0", "licurl": "https://creativecommons.org/licenses/by/3.0", "commons": "images/s_artery_vein_micro.jpg", "img": "images/s_artery_vein_micro.jpg", "more": [], "notes": ["Commons micrograph (OpenStax) had 'Artery'/'Vein' printed in the lumen – masked for the identify step."]}, {"id": "s_spinal_cord", "name": "Spinal cord", "day": "Day 3 · Nervous tissue", "course": "images/course/spinal_cord.jpg", "identify": ["Oval cross section with central butterfly/H-shaped gray matter", "Central canal lined by ependyma", "White matter on the outside", "Dorsal (posterior) and ventral (anterior) horns; anterior median fissure", "Silver stain in course slide: brown/black"], "label": ["Gray matter (somas or neuronal bodies)", "Dorsal and ventral horns", "Ependyma (ependymocytes) lining the central canal", "Neuronal bodies (large multipolar motor neurons in ventral horn)", "White matter", "Axon (transversal)", "Myelin sheath", "Axon + myelin sheath (longitudinal)", "Anterior median fissure"], "layers": ["White matter (outer)", "Gray matter (inner, H-shaped)", "Central canal with ependyma"], "model": "This is the spinal cord in cross section (silver stain). In the centre is the central canal lined by ependyma (ependymocytes). Around it is the H- or butterfly-shaped gray matter, with dorsal and ventral horns, containing the somas or neuronal bodies; the large multipolar neurons in the ventral horns are motor neurons. Outside is the white matter, made of axons with their myelin sheaths: cut transversally they appear as small rings (axon in the centre surrounded by myelin), and cut longitudinally as fibres of axon plus myelin sheath. The ventral side shows the anterior median fissure.", "key": ["Spinal cord", "Central canal + ependyma", "Gray matter (H shape) = neuronal bodies (somas), horns", "White matter = axons + myelin sheath", "Gray inside, white outside (opposite of brain)"], "src": "https://commons.wikimedia.org/wiki/File:Spinal_cord_(254_21)_Mammal;_cross-section.jpg", "title": "File:Spinal cord (254 21) Mammal; cross-section.jpg", "author": "Doc. RNDr. Josef Reischig, CSc.", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "images/s_spinal_cord.jpg", "img": "images/s_spinal_cord.jpg", "more": [], "notes": []}, {"id": "s_nerve_cross", "name": "Peripheral nerve – cross section", "day": "Day 3 · Nervous tissue", "course": "images/course/peripheral_nerve.jpg", "identify": ["Round bundles (fascicles) wrapped in connective tissue", "Inside: many small circles = axons with myelin sheaths (clear halo)", "Nuclei of Schwann cells / fibroblasts"], "label": ["Epineurium (dense CT around the whole nerve)", "Perineurium (around each fascicle)", "Endoneurium (loose CT around each fibre)", "Fascicles", "Axon", "Myelin sheath", "Schwann cells or fibroblasts"], "layers": ["Epineurium", "Perineurium around each fascicle", "Endoneurium around each fibre"], "model": "This is a peripheral nerve in cross section. The whole nerve is surrounded by the epineurium, dense connective tissue, and it is divided into fascicles, each wrapped by the perineurium. Inside each fascicle there are many nerve fibres cut transversally: each shows a central axon surrounded by a clear myelin sheath, and each fibre is surrounded by delicate loose connective tissue, the endoneurium. The nuclei between the fibres belong to Schwann cells or fibroblasts.", "key": ["Peripheral nerve, cross section", "Fascicles", "Epineurium / perineurium / endoneurium (connective tissue)", "Axon", "Myelin sheath", "Schwann cells / fibroblasts"], "src": "https://commons.wikimedia.org/wiki/File:Peripheral_nerve,_cross_section.jpg", "title": "File:Peripheral nerve, cross section.jpg", "author": "unknown", "license": "CC BY-SA 3.0", "licurl": "http://creativecommons.org/licenses/by-sa/3.0/", "commons": "images/s_nerve_cross.jpg", "img": "images/s_nerve_cross.jpg", "more": [], "notes": []}, {"id": "s_nerve_long", "name": "Peripheral nerve – longitudinal section", "day": "Day 3 · Nervous tissue", "course": "images/course/peripheral_nerve.jpg", "identify": ["Long, parallel, wavy pale fibres (zig-zag 'herring-bone' pattern)", "Elongated nuclei (Schwann cells / fibroblasts)", "Nodes of Ranvier as narrowings"], "label": ["Loose connective tissue (guide: 'smooth connective tissue')", "Axon", "Ranvier node", "Schwann cells or fibroblasts", "Myelin sheath"], "layers": ["Connective tissue sheath", "Parallel nerve fibres"], "model": "This is a peripheral nerve in longitudinal section. It is covered and divided by loose connective tissue. The nerve fibres run parallel and slightly wavy: each has a central axon surrounded by a myelin sheath, interrupted at the nodes of Ranvier. The elongated nuclei between the fibres belong to Schwann cells or fibroblasts.", "key": ["Peripheral nerve, longitudinal section", "Parallel wavy fibres", "Axon + myelin sheath", "Ranvier node", "Schwann cells / fibroblasts", "Connective tissue"], "src": "https://commons.wikimedia.org/wiki/File:EvG_nerve_and_neuroma.jpg", "title": "File:EvG nerve and neuroma.jpg", "author": "Jensflorian", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "images/s_nerve_long_a.jpg", "img": "images/course/peripheral_nerve_unlabeled.jpg", "more": [], "notes": ["Look-alikes: tendon (straighter, very dense pink collagen, fewer nuclei) and smooth muscle (pink cytoplasm, cigar-shaped central nuclei). Nerve fibres look pale/foamy because myelin is dissolved in processing."]}, {"id": "s_ganglion", "name": "Sensory ganglion", "day": "Day 3 · Nervous tissue", "course": "images/course/sensory_ganglion.jpg", "identify": ["Large round neuronal bodies with big nucleus and nucleolus", "Each surrounded by a ring of small satellite cells", "Bundles of nerve fibres running through", "Connective tissue capsule"], "label": ["Capsule (irregular dense connective tissue)", "Neuronal bodies", "Neuron nucleus", "Satellite cells", "Loose connective tissue (guide: 'smooth connective tissue')", "Axons + myelin sheaths", "Nerve (longitudinal)"], "layers": ["Capsule", "Groups of neuronal bodies", "Bundles of nerve fibres"], "model": "This is a sensory (spinal / dorsal root) ganglion. It is surrounded by a capsule of irregular dense connective tissue. Inside there are groups of large, round neuronal bodies (pseudounipolar sensory neurons) with a central nucleus and a prominent nucleolus; each is surrounded by a ring of small satellite cells. Between the groups of neurons run bundles of axons with myelin sheaths – the nerve, seen in longitudinal section – with loose connective tissue. There are no synapses in a sensory ganglion.", "key": ["Sensory ganglion", "Capsule – irregular dense CT", "Large round neuronal bodies, central nucleus", "Satellite cells around each soma", "Axons + myelin sheaths", "Connective tissue"], "src": "https://commons.wikimedia.org/wiki/File:1318b_Dorsal_Root_Ganglion.jpg", "title": "File:1318b Dorsal Root Ganglion.jpg", "author": "OpenStax", "license": "CC BY 4.0", "licurl": "https://creativecommons.org/licenses/by/4.0", "commons": "images/s_ganglion.jpg", "img": "images/s_ganglion.jpg", "more": [], "notes": []}];
window.ITEMS=[{"id": "animal_cell", "cat": "Extra · Cells", "name": "Animal cell (general)", "labels": ["Cell (plasma) membrane", "Nucleus with nucleolus", "Cytoplasm", "No cell wall, no large central vacuole, no chloroplasts"], "fn": "Basic unit of animal tissues; flexible membrane permits varied shapes, endocytosis and movement.", "img": "images/animal_cell.jpg", "src": "https://commons.wikimedia.org/wiki/File:Nucleus_in_human_cheek_cell.jpg", "title": "File:Nucleus in human cheek cell.jpg", "author": "Krishna satya 333", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "plant_cell", "cat": "Extra · Cells", "name": "Plant cell (e.g. Elodea leaf)", "labels": ["Cellulose cell wall", "Chloroplasts", "Large central vacuole (pushes cytoplasm to edge)", "Nucleus"], "fn": "Rigid wall gives support (turgor); chloroplasts photosynthesise; vacuole stores water/solutes.", "img": "images/plant_cell.jpg", "src": "https://commons.wikimedia.org/wiki/File:Anacharis_Magnified.jpg", "title": "File:Anacharis Magnified.jpg", "author": "Lilyviolet", "license": "CC BY 4.0", "licurl": "https://creativecommons.org/licenses/by/4.0"}, {"id": "onion_epidermis", "cat": "Extra · Cells", "name": "Onion epidermis", "labels": ["Brick-shaped, tightly packed cells", "Cell wall", "Nucleus (stains with iodine/methylene blue)", "No chloroplasts (bulb scale is underground)"], "fn": "Protective outer layer of the bulb scale leaf; classic plant-cell slide.", "img": "images/onion_epidermis.jpg", "src": "https://commons.wikimedia.org/wiki/File:Onion_Epidermis_Cells_W.M._40x_-_187.jpg", "title": "File:Onion Epidermis Cells W.M. 40x - 187.jpg", "author": "loganrickert", "license": "CC BY 2.0", "licurl": "https://creativecommons.org/licenses/by/2.0"}, {"id": "cheek_cells", "cat": "Extra · Cells", "name": "Human cheek (buccal) cells", "labels": ["Flat, irregular polygonal cells", "Central nucleus (stained)", "Plasma membrane only – no wall"], "fn": "Non-keratinised stratified squamous epithelium lining mouth; protects against abrasion.", "img": "images/cheek_cells.jpg", "src": "https://commons.wikimedia.org/wiki/File:Human_Cheek_Cells_(Methylene_Blue_Stain).jpg", "title": "File:Human Cheek Cells (Methylene Blue Stain).jpg", "author": "Fritzmann2002", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "mitosis_overview", "cat": "Extra · Mitosis (onion root tip)", "name": "Onion root tip – mitosis overview", "labels": ["Apical meristem (zone of cell division)", "Most cells in interphase", "Scattered cells in mitotic stages"], "fn": "Meristem cells divide rapidly for root growth – ideal for seeing mitosis.", "img": "images/mitosis_overview.jpg", "src": "https://commons.wikimedia.org/wiki/File:Onion_Root_Tip_Cells_Mitosis.jpg", "title": "File:Onion Root Tip Cells Mitosis.jpg", "author": "Catfaster", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "interphase", "cat": "Extra · Mitosis (onion root tip)", "name": "Interphase", "labels": ["Intact nucleus and nuclear envelope", "Visible nucleolus", "Chromatin diffuse – no distinct chromosomes"], "fn": "Growth and DNA replication (G1, S, G2); longest phase so most common cell on the slide.", "img": "images/interphase.jpg", "src": "https://commons.wikimedia.org/wiki/File:Interphase_and_Metaphase_labeled_on_Onion_Root_Microscopic_Image.png", "title": "File:Interphase and Metaphase labeled on Onion Root Microscopic Image.png", "author": "Natalierussell77", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "prophase", "cat": "Extra · Mitosis (onion root tip)", "name": "Prophase", "labels": ["Chromosomes condensing into visible threads", "Nucleolus disappearing", "Nuclear envelope breaking down (late)"], "fn": "Chromatin condenses so chromosomes can be moved; spindle starts to form.", "img": "images/prophase.jpg", "src": "https://commons.wikimedia.org/wiki/File:Mitosis_in_Onion_Root_-_various_stages_(Prophase_and_Interphase).jpg", "title": "File:Mitosis in Onion Root - various stages (Prophase and Interphase).jpg", "author": "Natalierussell77", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "metaphase", "cat": "Extra · Mitosis (onion root tip)", "name": "Metaphase", "labels": ["Chromosomes lined up on the equator (metaphase plate)", "Spindle fibres attached at centromeres"], "fn": "Alignment checkpoint ensuring each daughter gets one chromatid of each chromosome.", "img": "images/metaphase.jpg", "src": "https://commons.wikimedia.org/wiki/File:Mitosis_(261_13)_Pressed;_root_meristem_of_onion_(cells_in_prophase,_metaphase,_anaphase,_telophase).jpg", "title": "File:Mitosis (261 13) Pressed; root meristem of onion (cells in prophase, metaphase, anaphase, telophase).jpg", "author": "Doc. RNDr. Josef Reischig, CSc.", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0"}, {"id": "anaphase", "cat": "Extra · Mitosis (onion root tip)", "name": "Anaphase", "labels": ["Sister chromatids separating", "V-shapes moving toward opposite poles"], "fn": "Spindle shortens, pulling identical chromatids to opposite poles.", "img": "images/anaphase.jpg", "src": "https://commons.wikimedia.org/wiki/File:Mitosis_in_Onion_Root_-_various_stages_(Anaphase_and_Interphase).jpg", "title": "File:Mitosis in Onion Root - various stages (Anaphase and Interphase).jpg", "author": "Natalierussell77", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "telophase", "cat": "Extra · Mitosis (onion root tip)", "name": "Telophase (+ cytokinesis)", "labels": ["Two chromosome groups at poles", "Nuclear envelopes re-forming", "Cell plate forming between (plant)"], "fn": "Two nuclei re-form; cell plate builds new wall to split the cell.", "img": "images/telophase.jpg", "src": "https://commons.wikimedia.org/wiki/File:Onion_root_mitosis.jpg", "title": "File:Onion root mitosis.jpg", "author": "staticd", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0"}, {"id": "simple_squamous", "cat": "Extra · Epithelium", "name": "Simple squamous epithelium", "labels": ["Single layer of flat cells", "Flattened, bulging nuclei"], "fn": "Diffusion/filtration – alveoli, glomeruli, endothelium, mesothelium.", "img": "images/simple_squamous.jpg", "src": "https://commons.wikimedia.org/wiki/File:Simple_squamous_epithelium.png", "title": "File:Simple squamous epithelium.png", "author": "Jmarchn", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0"}, {"id": "simple_cuboidal", "cat": "Extra · Epithelium", "name": "Simple cuboidal epithelium", "labels": ["Single layer of cube-shaped cells", "Round central nuclei", "Often lines tubules (kidney)"], "fn": "Secretion and absorption – kidney tubules, gland ducts, thyroid follicles.", "img": "images/simple_cuboidal.jpg", "src": "https://commons.wikimedia.org/wiki/File:Simple_cuboidal_epithelium.png", "title": "File:Simple cuboidal epithelium.png", "author": "Jmarchn", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0"}, {"id": "simple_columnar", "cat": "Extra · Epithelium", "name": "Simple columnar epithelium", "labels": ["Single layer of tall cells", "Oval nuclei near base, in a row", "Goblet cells; possible microvilli/brush border"], "fn": "Absorption and secretion of mucus/enzymes – stomach, intestine.", "img": "images/simple_columnar.jpg", "src": "https://commons.wikimedia.org/wiki/File:Simple_columnar_epithelium.png", "title": "File:Simple columnar epithelium.png", "author": "unknown", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0"}, {"id": "stratified_squamous", "cat": "Extra · Epithelium", "name": "Stratified squamous epithelium", "labels": ["Many layers", "Basal cells cuboidal; surface cells flattened", "± keratin layer (skin)"], "fn": "Protection from abrasion – skin (keratinised), oesophagus, mouth, vagina.", "img": "images/stratified_squamous.jpg", "src": "https://commons.wikimedia.org/wiki/File:Stratified_squamous_epithelium.png", "title": "File:Stratified squamous epithelium.png", "author": "Jmarchn", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0"}, {"id": "pseudostratified", "cat": "Extra · Epithelium", "name": "Pseudostratified ciliated columnar", "labels": ["Single layer but nuclei at different heights", "All cells touch basement membrane", "Cilia + goblet cells"], "fn": "Secretes mucus and moves it via cilia – trachea, bronchi (respiratory epithelium).", "img": "images/pseudostratified.jpg", "src": "https://commons.wikimedia.org/wiki/File:Histology-_Pseudostratified_ciliated_columnar_epithelium_t.s._trachea.png", "title": "File:Histology- Pseudostratified ciliated columnar epithelium t.s. trachea.png", "author": "Eugeenia Wen", "license": "CC BY 4.0", "licurl": "https://creativecommons.org/licenses/by/4.0"}, {"id": "transitional", "cat": "Extra · Epithelium", "name": "Transitional epithelium (urothelium)", "labels": ["Several layers", "Dome-shaped (umbrella) surface cells", "Cells flatten when stretched"], "fn": "Stretches without tearing – bladder, ureters, urethra.", "img": "images/transitional.jpg", "src": "https://commons.wikimedia.org/wiki/File:Histology_of_transitional_epithelium.jpg", "title": "File:Histology of transitional epithelium.jpg", "author": "Veeresh likhitha", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "blood_smear", "cat": "Extra · Blood", "name": "Blood smear overview", "labels": ["Many pink biconcave RBCs", "Occasional WBCs with purple nuclei", "Small platelet fragments"], "fn": "Survey of formed elements; differential WBC count.", "img": "images/blood_smear.jpg", "src": "https://commons.wikimedia.org/wiki/File:Normal_Adult_Blood_Smear.JPG", "title": "File:Normal Adult Blood Smear.JPG", "author": "Keith Chambers", "license": "CC BY-SA 3.0", "licurl": "https://creativecommons.org/licenses/by-sa/3.0"}, {"id": "rbc", "cat": "Extra · Blood", "name": "Red blood cells (erythrocytes)", "labels": ["Anucleate", "Biconcave disc with pale centre", "~7–8 µm"], "fn": "Carry O₂ (and some CO₂) on haemoglobin.", "img": "images/rbc.jpg", "src": "https://commons.wikimedia.org/wiki/File:Human_Red_Blood_Cells.jpg", "title": "File:Human Red Blood Cells.jpg", "author": "Naz Amann", "license": "CC BY 4.0", "licurl": "https://creativecommons.org/licenses/by/4.0"}, {"id": "neutrophil", "cat": "Extra · Blood", "name": "Neutrophil", "labels": ["Multilobed nucleus (3–5 lobes)", "Pale/faint granules", "Most common WBC (~60%)"], "fn": "First responder phagocyte for bacteria.", "img": "images/neutrophil.jpg", "src": "https://commons.wikimedia.org/wiki/File:Neutrophils_with_intracellular_bacteria_on_peripheral_blood_smear.png", "title": "File:Neutrophils with intracellular bacteria on peripheral blood smear.png", "author": "Spicy", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "lymphocyte", "cat": "Extra · Blood", "name": "Lymphocyte", "labels": ["Large round dark nucleus", "Thin rim of blue cytoplasm", "About RBC size or slightly larger"], "fn": "Adaptive immunity – B cells (antibodies), T cells, NK cells.", "img": "images/lymphocyte.jpg", "src": "https://commons.wikimedia.org/wiki/File:Lymphocytes.jpg", "title": "File:Lymphocytes.jpg", "author": "Dr Graham Beards", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "monocyte", "cat": "Extra · Blood", "name": "Monocyte", "labels": ["Largest WBC", "Kidney/horseshoe-shaped nucleus", "Grey-blue cytoplasm"], "fn": "Becomes macrophage in tissues; phagocytosis, antigen presentation.", "img": "images/monocyte.jpg", "src": "https://commons.wikimedia.org/wiki/File:Monocyte.jpg", "title": "File:Monocyte.jpg", "author": "unknown", "license": "CC BY-SA 3.0", "licurl": "http://creativecommons.org/licenses/by-sa/3.0/"}, {"id": "eosinophil", "cat": "Extra · Blood", "name": "Eosinophil", "labels": ["Bilobed nucleus", "Large orange-red granules"], "fn": "Fights parasites; modulates allergic reactions.", "img": "images/eosinophil.jpg", "src": "https://commons.wikimedia.org/wiki/File:Eosinophil_blood_smear.JPG", "title": "File:Eosinophil blood smear.JPG", "author": "Bobjgalindo", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "basophil", "cat": "Extra · Blood", "name": "Basophil", "labels": ["Dark purple-blue granules obscuring nucleus", "Bilobed/S-shaped nucleus", "Rarest WBC (<1%)"], "fn": "Releases histamine and heparin in inflammation/allergy.", "img": "images/basophil.jpg", "src": "https://commons.wikimedia.org/wiki/File:Basophil_granulocyte_(16670067236).jpg", "title": "File:Basophil granulocyte (16670067236).jpg", "author": "Hanna Sörensson from Karlstad, Sweden", "license": "CC BY-SA 2.0", "licurl": "https://creativecommons.org/licenses/by-sa/2.0"}, {"id": "platelets", "cat": "Extra · Blood", "name": "Platelets (thrombocytes)", "labels": ["Tiny purple cell fragments", "No nucleus", "Often in clumps between RBCs"], "fn": "Blood clotting – form platelet plug.", "img": "images/platelets.jpg", "src": "https://commons.wikimedia.org/wiki/File:WBC_(neutrophil)_at_centre,_numerous_erythrocytes_and_platelets_(dot_like_bodies)_in_Wright%27s_stained_peripheral_blood_smear_(PBS)_microscopy.jpg", "title": "File:WBC (neutrophil) at centre, numerous erythrocytes and platelets (dot like bodies) in Wright's stained peripheral blood smear (PBS) microscopy.jpg", "author": "Ajay Kumar Chaurasiya", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "skeletal_muscle", "cat": "Extra · Muscle", "name": "Skeletal muscle", "labels": ["Long cylindrical fibres", "Striations", "Many peripheral nuclei (multinucleate)"], "fn": "Voluntary movement of skeleton, posture, heat.", "img": "images/skeletal_muscle.jpg", "src": "https://commons.wikimedia.org/wiki/File:Skeletal_muscle_-_longitudinal_section.jpg", "title": "File:Skeletal muscle - longitudinal section.jpg", "author": "unknown", "license": "CC BY-SA 3.0", "licurl": "http://creativecommons.org/licenses/by-sa/3.0/"}, {"id": "smooth_muscle", "cat": "Extra · Muscle", "name": "Smooth muscle", "labels": ["Spindle-shaped cells", "No striations", "Single central nucleus"], "fn": "Involuntary contraction – gut peristalsis, vessel diameter, bladder.", "img": "images/smooth_muscle.jpg", "src": "https://commons.wikimedia.org/wiki/File:Smooth_muscle_-_histology.jpg", "title": "File:Smooth muscle - histology.jpg", "author": "Juan Carlos Fonseca Mata", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "cardiac_muscle", "cat": "Extra · Muscle", "name": "Cardiac muscle", "labels": ["Branched striated cells", "Intercalated discs", "1–2 central nuclei"], "fn": "Involuntary rhythmic pumping of the heart; discs couple cells electrically.", "img": "images/cardiac_muscle.jpg", "src": "https://commons.wikimedia.org/wiki/File:Muscle_Tissue_Intercalated_Discs_in_Cardiac_Muscle_(27061947267).jpg", "title": "File:Muscle Tissue Intercalated Discs in Cardiac Muscle (27061947267).jpg", "author": "Berkshire Community College  Bioscience Image Library", "license": "CC0", "licurl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}, {"id": "neuron", "cat": "Extra · Nervous", "name": "Nervous tissue / neuron", "labels": ["Cell body (soma) with nucleus", "Dendrites", "Axon", "Neuroglia (small surrounding nuclei)"], "fn": "Neurons transmit impulses; glia support and insulate.", "img": "images/neuron.jpg", "src": "https://commons.wikimedia.org/wiki/File:Nervous_Tissue_Spinal_Cord_Motor_Neuron_(41850850692).jpg", "title": "File:Nervous Tissue Spinal Cord Motor Neuron (41850850692).jpg", "author": "Berkshire Community College  Bioscience Image Library", "license": "CC0", "licurl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}, {"id": "motor_neuron", "cat": "Extra · Nervous", "name": "Motor neuron smear (spinal cord)", "labels": ["Large multipolar cell body", "Prominent nucleus and nucleolus", "Nissl bodies", "Many processes"], "fn": "Carries impulses from CNS to skeletal muscle.", "img": "images/motor_neuron.jpg", "src": "https://commons.wikimedia.org/wiki/File:Nervous_Tissue_Spinal_Cord_Motor_Neuron_(41850849912).jpg", "title": "File:Nervous Tissue Spinal Cord Motor Neuron (41850849912).jpg", "author": "Berkshire Community College  Bioscience Image Library", "license": "CC0", "licurl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}, {"id": "compact_bone", "cat": "Extra · Connective", "name": "Compact bone (ground section)", "labels": ["Osteons (Haversian systems)", "Central (Haversian) canal", "Concentric lamellae", "Lacunae with canaliculi"], "fn": "Support, protection, mineral storage; canals carry vessels/nerves.", "img": "images/compact_bone.jpg", "src": "https://commons.wikimedia.org/wiki/File:Compact_bone_histology_2014.jpg", "title": "File:Compact bone histology 2014.jpg", "author": "Athikhun.suw", "license": "CC BY-SA 4.0", "licurl": "https://creativecommons.org/licenses/by-sa/4.0"}, {"id": "hyaline_cartilage", "cat": "Extra · Connective", "name": "Hyaline cartilage", "labels": ["Glassy, smooth matrix", "Chondrocytes in lacunae (often in groups)", "Perichondrium"], "fn": "Smooth articular surfaces, trachea rings, costal cartilage, fetal skeleton.", "img": "images/hyaline_cartilage.jpg", "src": "https://commons.wikimedia.org/wiki/File:Histology_of_articular_cartilage_zones.jpg", "title": "File:Histology of articular cartilage zones.jpg", "author": "Catherine A. Bautista, Hee Jun Park, Courtney M. Mazur, Roy K. Aaron, Bahar Bilgen", "license": "CC0", "licurl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}, {"id": "elastic_cartilage", "cat": "Extra · Connective", "name": "Elastic cartilage", "labels": ["Dark elastic fibres in matrix", "Chondrocytes in lacunae"], "fn": "Flexible support that recoils – ear pinna, epiglottis.", "img": "images/elastic_cartilage.jpg", "src": "https://commons.wikimedia.org/wiki/File:Connective_Tissue_Elastic_Cartilage_(41812804042).jpg", "title": "File:Connective Tissue Elastic Cartilage (41812804042).jpg", "author": "Berkshire Community College  Bioscience Image Library", "license": "CC0", "licurl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}, {"id": "fibrocartilage", "cat": "Extra · Connective", "name": "Fibrocartilage", "labels": ["Thick parallel collagen bundles", "Chondrocytes in rows", "No perichondrium"], "fn": "Resists compression/tension – intervertebral discs, pubic symphysis, menisci.", "img": "images/fibrocartilage.jpg", "src": "https://commons.wikimedia.org/wiki/File:Connective_Tissue_Fibrocartilage_(27988651538).jpg", "title": "File:Connective Tissue Fibrocartilage (27988651538).jpg", "author": "Berkshire Community College  Bioscience Image Library", "license": "CC0", "licurl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}];
window.VERT=[{"n": 1, "q": "Which structure forms the posterior wall of the vertebral foramen?", "opts": ["Pedicle", "Lamina", "Vertebral body", "Transverse process"], "ans": "B) Lamina", "why": "The laminae close the arch posteriorly; the body is anterior, the pedicles lateral."}, {"n": 2, "q": "Transverse foramina are a distinguishing feature of which vertebrae?", "opts": ["Thoracic", "Lumbar", "Cervical", "Sacral"], "ans": "C) Cervical", "why": "Only cervical vertebrae have them, for the vertebral vessels."}, {"n": 3, "q": "Which vertebra has no body and no spinous process?", "opts": ["C1 (atlas)", "C2 (axis)", "C7", "T1"], "ans": "A) C1 (atlas)", "why": "The atlas is a ring of anterior and posterior arches with lateral masses."}, {"n": 4, "q": "Costal facets on the vertebral bodies are characteristic of:", "opts": ["Cervical vertebrae", "Thoracic vertebrae", "Lumbar vertebrae", "Coccygeal vertebrae"], "ans": "B) Thoracic vertebrae", "why": "Thoracic bodies articulate with rib heads."}, {"n": 5, "q": "Lumbar facet joints are oriented mainly in which plane, favouring which movement?", "opts": ["Coronal – rotation", "Sagittal – flexion/extension", "Horizontal – lateral flexion", "Coronal – flexion/extension"], "ans": "B) Sagittal – flexion/extension", "why": "Near-sagittal lumbar facets allow flexion/extension and limit rotation."}, {"n": 6, "q": "Which ligament limits extension of the vertebral column?", "opts": ["Posterior longitudinal ligament", "Ligamentum flavum", "Anterior longitudinal ligament", "Supraspinous ligament"], "ans": "C) Anterior longitudinal ligament", "why": "The ALL on the anterior bodies is the only one that resists extension."}, {"n": 7, "q": "Intervertebral discs most commonly herniate in which direction?", "opts": ["Anteriorly", "Posterolaterally", "Directly posteriorly in the midline", "Superiorly into the body only"], "ans": "B) Posterolaterally", "why": "Thin posterior annulus and narrow PLL leave the posterolateral area weakest."}, {"n": 8, "q": "Spondylolysis is a defect in the:", "opts": ["Vertebral body", "Pedicle", "Pars interarticularis", "Spinous process"], "ans": "C) Pars interarticularis", "why": "It is a stress fracture of the pars, most often at L5."}, {"n": 9, "q": "Mammillary processes are found on which vertebrae?", "opts": ["Cervical", "Thoracic", "Lumbar", "Sacral"], "ans": "C) Lumbar", "why": "They sit on the superior articular processes of lumbar vertebrae (multifidus attachment)."}, {"n": 10, "q": "The vertebral arch is formed by two ________ and two ________.", "opts": [], "ans": "pedicles; laminae", "why": "Pedicles attach to the body, laminae meet posteriorly."}, {"n": 11, "q": "A typical vertebra has seven processes: one ________, two ________ and four ________.", "opts": [], "ans": "spinous; transverse; articular", "why": "Four articular = two superior + two inferior."}, {"n": 12, "q": "The tooth-like process of C2 is called the ________ (or odontoid process).", "opts": [], "ans": "dens", "why": "It projects up to articulate with the anterior arch of C1."}, {"n": 13, "q": "C7 is called the vertebra ________ because of its long, palpable spinous process.", "opts": [], "ans": "prominens", "why": "First clearly palpable spinous process at the base of the neck."}, {"n": 14, "q": "The intervertebral disc consists of an outer ________ ________ and an inner ________ ________.", "opts": [], "ans": "annulus fibrosus; nucleus pulposus", "why": "Fibrocartilage rings surround a gelatinous core."}, {"n": 15, "q": "The spinal nerve exits the vertebral column through the ________ ________, formed by the notches of adjacent pedicles.", "opts": [], "ans": "intervertebral foramen", "why": "Superior and inferior vertebral notches of adjacent vertebrae form it."}];
window.THEORY=[{"q": "Four basic tissue types (seminar)", "a": "Epithelial, connective, muscular and nervous. All organs are made of just these four."}, {"q": "What is a tissue?", "a": "A collection/group of cells organised to carry out one or more specific functions."}, {"q": "Two types of epithelial tissue", "a": "Lining (covering) epithelium and glandular epithelium."}, {"q": "How is lining epithelium classified?", "a": "By number of layers (simple = one; stratified = several; pseudostratified = one layer that looks layered) and by shape of the surface cells (squamous, cuboidal, columnar). Plus transitional (urothelium)."}, {"q": "Exocrine vs endocrine gland", "a": "Exocrine glands secrete onto a surface through ducts (e.g. sweat gland). Endocrine glands have no ducts and secrete hormones into the blood (e.g. thyroid)."}, {"q": "Connective tissue proper: types", "a": "Loose and dense; dense is either regular (tendon) or irregular (dermis, perichondrium, periosteum, capsules)."}, {"q": "Specialized connective tissues (seminar)", "a": "Adipose (white, brown), cartilage (hyaline, elastic, fibrocartilage), bone (compact, spongy) and blood."}, {"q": "Dense regular vs dense irregular CT", "a": "Regular: collagen type I bundles parallel, fibroblasts in rows (tendon). Irregular: collagen bundles in all directions (dermis)."}, {"q": "Main fibre in CT proper, tendon, bone", "a": "Collagen type I."}, {"q": "Main collagen in hyaline cartilage", "a": "Collagen type II."}, {"q": "Three types of cartilage", "a": "Hyaline (trachea, articular), elastic (ear, epiglottis), fibrocartilage (intervertebral disc, menisci)."}, {"q": "Cells of bone", "a": "Osteoblasts (make matrix, on surfaces), osteocytes (in lacunae, connected by canaliculi), osteoclasts (large, multinucleated, resorb bone)."}, {"q": "Compact vs spongy bone", "a": "Compact: osteons (Haversian systems) with Haversian canal + concentric lamellae. Spongy: trabeculae without osteons, spaces filled with bone marrow."}, {"q": "Muscle tissue classification (seminar)", "a": "Smooth and striated; striated is skeletal or cardiac."}, {"q": "Skeletal muscle features", "a": "Long cylindrical multinucleated fibres, peripheral nuclei, striations, voluntary."}, {"q": "Cardiac muscle features", "a": "Striated, branched cardiomyocytes, 1–2 central nuclei, intercalated disks, involuntary."}, {"q": "Smooth muscle features", "a": "Spindle-shaped cells, single central cigar-shaped nucleus, no striations, involuntary (vessel walls, gut)."}, {"q": "Nervous tissue cells", "a": "Neurons (soma, dendrites, axon) and glia. CNS glia: astrocytes, oligodendrocytes, microglia, ependymal cells. PNS glia: Schwann cells, satellite cells."}, {"q": "Who makes myelin?", "a": "Oligodendrocytes in the CNS; Schwann cells in the PNS."}, {"q": "Gray vs white matter", "a": "Gray: neuronal bodies (somas). White: myelinated axons. Spinal cord: gray inside, white outside."}, {"q": "Connective tissue layers of a peripheral nerve", "a": "Epineurium (whole nerve), perineurium (each fascicle), endoneurium (each fibre)."}, {"q": "Three tunics of a blood vessel", "a": "Tunica intima (endothelium), tunica media (smooth muscle), tunica adventitia (connective tissue)."}, {"q": "Hematoxylin stains…", "a": "Basic dye: stains acidic (basophilic) structures – DNA/RNA, nuclei – blue/purple."}, {"q": "Eosin stains…", "a": "Acidic dye: stains basic (acidophilic/eosinophilic) structures – cytoplasm, collagen/extracellular matrix – pink."}, {"q": "Steps of histological processing (seminar)", "a": "Obtain organ/tissue → fixation → processing (dehydration, clearing) → embedding in paraffin → sectioning (microtome) → floating → mounting on slide → staining → coverslipping → histological sample."}, {"q": "Parts of the optic microscope (seminar)", "a": "1 eyepiece (ocular lens), 2 objective turret, 3 objective lenses, 4 stage, 5 diaphragm, 6 light source, 7 coarse and fine focus knobs, 8 mechanical stage controls."}, {"q": "Objective lenses (seminar)", "a": "4x, 10x, 20x, 40x, 100x (100x needs immersion oil). Always start at 4x to find and identify the tissue, then go up."}, {"q": "Total magnification", "a": "Objective × eyepiece (usually 10x): e.g. 40x objective → 400x."}];
window.TMCQ=[{"q": "Which is NOT one of the four basic tissues?", "o": ["Epithelial", "Connective", "Glandular", "Nervous"], "c": 2, "w": "Glandular is a subtype of epithelial tissue."}, {"q": "Tendon is an example of…", "o": ["Loose CT", "Dense regular CT", "Dense irregular CT", "Hyaline cartilage"], "c": 1, "w": "Parallel collagen type I bundles with fibroblasts in rows."}, {"q": "The dermis is mainly…", "o": ["Dense irregular CT", "Dense regular CT", "Adipose tissue", "Elastic cartilage"], "c": 0, "w": "Collagen bundles run in all directions."}, {"q": "Blood is classified in the seminar as…", "o": ["Epithelial tissue", "Specialized connective tissue", "Muscle tissue", "Loose CT"], "c": 1, "w": "Specialized CT with cells in a liquid matrix (plasma)."}, {"q": "Hematoxylin stains nuclei because it…", "o": ["Is acidic and binds proteins", "Is basic and binds DNA/RNA", "Dissolves lipids", "Binds collagen"], "c": 1, "w": "Nucleic acids are acidic, so they take the basic dye."}, {"q": "Which muscle has intercalated disks?", "o": ["Skeletal", "Smooth", "Cardiac", "All striated"], "c": 2, "w": "Only cardiac."}, {"q": "Peripheral nuclei + multinucleated striated fibres =", "o": ["Cardiac", "Skeletal", "Smooth", "Myoepithelial"], "c": 1, "w": "Skeletal muscle, e.g. tongue."}, {"q": "Collagen of hyaline cartilage matrix", "o": ["Type I", "Type II", "Type III", "Type IV"], "c": 1, "w": "Type II; type I is in bone, tendon, dermis."}, {"q": "Which objective needs immersion oil?", "o": ["10x", "20x", "40x", "100x"], "c": 3, "w": "The 100x objective."}, {"q": "Epithelium with one layer but nuclei at different heights", "o": ["Stratified columnar", "Transitional", "Pseudostratified columnar", "Simple cuboidal"], "c": 2, "w": "All cells touch the basement membrane – trachea."}, {"q": "Myelin in peripheral nerves is formed by", "o": ["Oligodendrocytes", "Schwann cells", "Satellite cells", "Astrocytes"], "c": 1, "w": "Oligodendrocytes do it in the CNS."}, {"q": "Osteons are found in", "o": ["Spongy bone", "Compact bone", "Hyaline cartilage", "Bone marrow"], "c": 1, "w": "Spongy bone has trabeculae without osteons."}, {"q": "Which is an endocrine gland on your list?", "o": ["Sweat gland", "Thyroid", "Seromucous tracheal glands", "Salivary gland"], "c": 1, "w": "No ducts; hormones go to blood."}, {"q": "Gray matter mainly contains", "o": ["Myelinated axons", "Neuronal bodies (somas)", "Collagen", "Adipocytes"], "c": 1, "w": "White matter = myelinated axons."}, {"q": "Satellite cells surround", "o": ["Axons in nerve", "Neuronal bodies in ganglia", "Chondrocytes", "Osteocytes"], "c": 1, "w": "Glia of PNS ganglia."}];
window.LOOK=[{"t": "Trachea vs esophagus", "a": "s_trachea", "b": null, "bn": "", "txt": "Trachea: ciliated pseudostratified columnar epithelium with goblet cells + hyaline cartilage ring. Esophagus (not on list): non-keratinized stratified squamous epithelium, NO cartilage, thick muscularis externa. Rule: cartilage + cilia → trachea."}, {"t": "Thick skin vs thin skin", "a": "s_thick_skin", "b": "images/course/sem_thin_skin.jpg", "bn": "", "txt": "Thick skin: huge keratin layer, stratum lucidum, sweat glands, NO hair follicles. Thin skin (right, seminar image): thin keratin, many hair follicles and sebaceous glands."}, {"t": "Tendon vs smooth muscle vs longitudinal nerve", "a": "s_tendon", "b": "images/s_nerve_long_a.jpg", "bn": "", "txt": "Tendon: dense bright-pink parallel collagen, few flat nuclei squeezed between bundles. Smooth muscle (artery media): cells with pink cytoplasm, one cigar-shaped central nucleus each, many nuclei. Nerve (longitudinal): pale, foamy, wavy zig-zag fibres, nodes of Ranvier, more nuclei (Schwann cells)."}, {"t": "Muscular artery vs vein", "a": "s_artery_vein", "b": null, "bn": "", "txt": "Artery: round lumen, thick tunica media of smooth muscle, wavy internal elastic lamina (and external), thick wall relative to lumen. Vein: larger irregular/collapsed lumen often with blood, thin media, adventitia is the thickest layer, no clear elastic laminae."}, {"t": "Compact vs spongy bone", "a": "s_compact_bone", "b": "images/course/spongy_bone_unlabeled.jpg", "bn": "Spongy / cancellous bone", "txt": "Compact (ground section, grey/brown, no marrow): osteons with Haversian canal, concentric lamellae, lacunae + canaliculi, Volkmann canals. Spongy (decalcified H&E, pink): thin trabeculae without osteons, marrow with hematopoietic cells in between, osteoblasts/osteoclasts on surfaces."}, {"t": "Spinal cord vs sensory ganglion vs peripheral nerve", "a": "s_spinal_cord", "b": "images/s_ganglion.jpg", "bn": "Sensory ganglion", "txt": "Spinal cord: oval, H-shaped gray matter inside, white matter outside, central canal with ependyma. Sensory ganglion: big round neuronal bodies each ringed by satellite cells + capsule + nerve fibre bundles. Peripheral nerve: NO neuronal bodies – only fibres (axon + myelin) in fascicles with epi/peri/endoneurium."}, {"t": "Peripheral nerve cross vs longitudinal", "a": "s_nerve_cross", "b": "images/course/peripheral_nerve_unlabeled.jpg", "bn": "Peripheral nerve – longitudinal section", "txt": "Cross: round fascicles full of small circles (axon dot + myelin halo). Longitudinal: parallel wavy fibres, nodes of Ranvier, elongated nuclei."}, {"t": "Tongue (skeletal) vs heart (cardiac)", "a": "s_tongue", "b": "images/s_heart.jpg", "bn": "Heart (cardiac muscle)", "txt": "Tongue: epithelium on top, fibres in 3 directions, peripheral nuclei, multinucleated, no branching. Heart: no epithelium, branched cells, 1–2 central nuclei, intercalated disks."}, {"t": "Thyroid vs other glands", "a": "s_thyroid", "b": null, "bn": "", "txt": "Thyroid: round follicles filled with pink colloid, lined by simple cuboidal epithelium, no ducts. Exocrine glands (e.g. sweat, salivary) have secretory units + ducts and no colloid store."}, {"t": "Hyaline cartilage (trachea) vs bone", "a": "s_trachea", "b": "images/s_compact_bone.jpg", "bn": "Compact bone (ground section)", "txt": "Cartilage: smooth glassy matrix, chondrocytes in lacunae (often isogenous groups), perichondrium, no canals. Bone: lamellae, osteocytes with canaliculi, Haversian canals."}];
